('10000000-0000-4000-8000-000000000001','ultima-luz','La última luz del museo',
insert into public.mm_suspects(id,case_id,name,description,motive,alibi) values
('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Clara Vidal','Conservadora. Conoce cada pieza del museo.','Una deuda amenaza su taller de restauración.','«Estuve en el laboratorio entre las 21:10 y las 21:25». '),
('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','Bruno Salas','Jefe de seguridad. Lleva doce años vigilando las salas.','Acaba de recibir un aviso de despido.','«Bajé a reiniciar el cuadro eléctrico a las 21:16». '),
('20000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001','Inés Duarte','Periodista cultural. Invitada a cubrir la exposición.','Una exclusiva podría salvar su revista.','«Estaba grabando una entrevista en el vestíbulo». '),
('20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000001','Mateo Ríos','Coleccionista y principal donante del museo.','Su oferta para comprar el zafiro fue rechazada.','«Llamé a mi abogado desde la terraza». ');
insert into mm_private.solutions values
('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',
insert into mm_private.clues(case_id,title,body,stage,private,position) values
('10000000-0000-4000-8000-000000000001','01 · La vitrina intacta','No hay señales de fuerza. La vitrina solo se abre con una credencial de conservación; las tarjetas de seguridad no sirven.',0,false,1),
('10000000-0000-4000-8000-000000000001','02 · Noventa segundos','El apagón comenzó a las 21:17:00 y acabó a las 21:18:30. El registro de la vitrina tiene batería propia.',0,false,2),
('10000000-0000-4000-8000-000000000001','El acceso C-04','La vitrina se abrió a las 21:17:32 con C-04. El registro no muestra intentos fallidos.',0,true,3),
('10000000-0000-4000-8000-000000000001','La cámara del laboratorio','A las 21:16:40 se ve a Clara salir del laboratorio hacia la sala del zafiro. Regresa a las 21:20.',0,true,4),
('10000000-0000-4000-8000-000000000001','Un audio continuo','La grabación de Inés no tiene cortes entre las 21:15 y las 21:21. Se oyen su voz y las fuentes del vestíbulo.',0,true,5),
('10000000-0000-4000-8000-000000000001','El técnico de guardia','El técnico confirma que Bruno estuvo con él ante el cuadro eléctrico desde las 21:16 hasta las 21:19.',0,true,6),
('10000000-0000-4000-8000-000000000001','03 · Credenciales nominales','El informe de accesos confirma que C-04 pertenece a Clara Vidal. El resto de sospechosos no tenía permiso de conservación.',1,false,7),
('10000000-0000-4000-8000-000000000001','04 · Una coartada que no encaja','La cámara, alimentada por batería, muestra que el laboratorio estuvo vacío de 21:16:40 a 21:20. Clara había declarado no haber salido.',1,false,8),
('10000000-0000-4000-8000-000000000001','Barniz azul','El precinto interior de la vitrina tiene barniz azul fresco. Ese lote se utiliza únicamente en el taller de Clara.',1,true,9),
('10000000-0000-4000-8000-000000000001','La llamada de Mateo','La operadora confirma una llamada de 21:14 a 21:23. La cámara de la terraza lo muestra allí durante todo ese intervalo.',1,true,10),
('10000000-0000-4000-8000-000000000001','Un embalaje de más','En el carro de restauración de Clara apareció una caja pesada que no figuraba en el inventario de esa tarde.',1,true,11),
('10000000-0000-4000-8000-000000000001','El temporizador','El corte no fue accidental. Se programó a las 20:50 desde el terminal del taller de conservación, mientras Clara era la única persona allí.',1,true,12);
